(function(){
  var root = (typeof window !== 'undefined') ? window : null;
  if (!root || root.TM_CSS_RETRY) return;
  var delays = [1000, 4000, 8000, 30000, 180000];

  function retryHref(href, count) {
    var sep = href.indexOf('?') >= 0 ? '&' : '?';
    return href + sep + 'cssRetry=' + Date.now() + '-' + count;
  }

  root.TM_CSS_LOADED = function(link) {
    if (!link) return;
    link.setAttribute('data-css-ok', '1');
    if (link._tmCssRetryTimer) {
      clearTimeout(link._tmCssRetryTimer);
      link._tmCssRetryTimer = null;
    }
  };

  root.TM_CSS_RETRY = function(link) {
    if (!link || link.getAttribute('data-css-ok') === '1') return;
    var count = parseInt(link.getAttribute('data-css-retry-count') || '0', 10);
    if (!isFinite(count) || count < 0) count = 0;
    var base = link.getAttribute('data-css-base') || link.getAttribute('href') || '';
    var fallback = link.getAttribute('data-css-fallback') || '';
    var useFallback = !!fallback && count >= 2 && count < 4;
    var target = useFallback ? fallback : base;
    if (!target) return;
    var delay = delays[Math.min(count, delays.length - 1)];
    link.setAttribute('data-css-retry-count', String(count + 1));
    if (link._tmCssRetryTimer) clearTimeout(link._tmCssRetryTimer);
    link._tmCssRetryTimer = setTimeout(function(){
      if (link.getAttribute('data-css-ok') === '1') return;
      link.href = retryHref(target, count + 1);
    }, delay);
    if (root.console && root.console.warn) {
      root.console.warn('[tm-css] stylesheet failed; retry scheduled in ' + delay + 'ms', base);
    }
  };
})();

/* 界面字号·早期应用（2026-06-10·治玩家双端「字太小」）。档位存 localStorage（设备本地偏好·
   不进存档），设置面板「界面显示」可调。--text-* token 全是 rem → 改 html 根字号即全局生效。
   在 head 同步应用，避免首屏先渲染小字再跳大。
   未设置时出厂默认自适应（2026-08-10·治高分屏字小反馈·只生效不落盘·显式选择永远优先）：
   ①按屏幕宽定档——≥3400 CSS px（4K@100% 等）取 1.6，≥2400（2K 2560@100%、4K@150% 等）取 1.35「特大」，
     否则 1.2「大」（owner 2026-06-10 二次拍板再调大）。取屏幕宽而非窗口宽：Electron 冷启动按存档窗口
     尺寸建窗、本块在 ready-to-show 全屏化之前执行，innerWidth 是旧窗口宽（出厂 1440×900）→ 2K 首启会误判。
   ②防双重放大——显式选了「渲染分辨率」固定舞台且舞台整体放大（stg>1）时字号默认 ÷舞台放大率折算
     （夹 0.9~1.6·取两位小数）：舞台缩放已把界面字图一起拉大，再叠字号档字会顶出面板；舞台缩小
     （APK 手机 stg<1）不折算，维持 ①的基础档。stg 按屏幕算（此时窗口未全屏·innerWidth 不可信）。
   自适应取值与 tm-patches.js _tmUiFontScaleDefault 一字不差（那处是高亮 fallback·两处须同步改）。 */
(function(){
  try {
    var s = parseFloat(localStorage.getItem('tm.uiFontScale'));
    if (!s || s < 0.8 || s > 1.6) {
      var w = 0, sh = 0; try { w = (window.screen && window.screen.availWidth) || window.innerWidth || 0; sh = (window.screen && window.screen.availHeight) || window.innerHeight || 0; } catch(_) {}
      s = (w >= 3400) ? 1.6 : (w >= 2400) ? 1.35 : 1.2;
      try {
        var res = localStorage.getItem('tm.fitResolution'), m = res && /^(\d{3,4})x(\d{3,4})$/.exec(res);
        if (m && w > 0 && sh > 0) {
          var stg = Math.min(w / (+m[1]), sh / (+m[2]));
          if (stg > 1) s = Math.round(Math.min(1.6, Math.max(0.9, s / stg)) * 100) / 100;
        }
      } catch(_) {}
    }
    if (s !== 1) document.documentElement.style.fontSize = (16 * s) + 'px';
  } catch (_) {}
})();

(function fillHomeRecent(){
  try{
    var idx = JSON.parse(localStorage.getItem('tm_save_index')||'{}');
    var arr = Object.keys(idx).map(function(k){ var v=idx[k]; v._slot=k; return v; }).filter(function(v){return v&&v.timestamp;}).sort(function(a,b){return b.timestamp-a.timestamp;}).slice(0,3);
    if (!arr.length) return;
    var host = document.getElementById('home-recent'); if(!host) return;
    var empty = document.getElementById('home-recent-empty'); if(empty) empty.remove();
    arr.forEach(function(s){
      var span = document.createElement('div');
      span.className = 'r-item';
      var isAuto = s._slot==='slot_0';
      var seal = isAuto ? '自' : '封';
      var label = (s.eraName||s.date||'') + (s.turn?(' 第'+s.turn+'回'):'');
      if (!label.trim()) label = s.name || '案卷';
      var meta = s.name || (isAuto ? '自动存档' : '手动存档');
      var sealNode = document.createElement('span');
      sealNode.className = 'r-seal';
      sealNode.textContent = seal;
      var textWrap = document.createElement('span');
      var nameNode = document.createElement('span');
      nameNode.className = 'r-name';
      nameNode.textContent = label;
      var metaNode = document.createElement('span');
      metaNode.className = 'r-meta';
      metaNode.textContent = meta;
      textWrap.appendChild(nameNode);
      textWrap.appendChild(metaNode);
      span.appendChild(sealNode);
      span.appendChild(textWrap);
      // 近事卡可点：进存档管理续卷（纯漏斗·走既有续卷入口）
      span.setAttribute('role','button');
      span.title = '启封此卷 · 打开存档管理';
      span.onclick = function(){ var b = document.getElementById('btn-load-save'); if (b) b.click(); };
      host.appendChild(span);
    });
  }catch(e){}
})();

// phase 14.1·载图入口·选 map-editor 导出 JSON·装 P.map·status 提示
window._loadMapEditorJSON = function(){
  if (typeof loadMapEditorDialog !== 'function'){
    alert('map-editor-to-game.js 未加载');
    return;
  }
  loadMapEditorDialog({ splitExclaves: true }).then(function(r){
    var gm = r.gm;
    if (typeof window.P === 'undefined'){
      // P 未初始化 (未开卷)·暂存 window.__pendingMap·开卷时择机装
      window.__pendingMap = gm;
      alert('地图已暂存·' + gm.regions.length + ' 区·开卷时自动装入');
    } else {
      window.P.map = gm;
      alert('地图已装入·' + gm.regions.length + ' 区 (' + gm.name + ')');
      if (typeof renderGameMap === 'function' && typeof showMapInGame === 'function'){
        // 不立即弹·让用户手动·避免打扰
      }
    }
  }).catch(function(err){
    if (err && err.message !== '未选文件') alert('载图失败·' + err.message);
  });
};

// 开卷启动后·若 __pendingMap 存·自动装
window._installPendingMapIfAny = function(){
  if (window.__pendingMap && typeof window.P !== 'undefined'){
    window.P.map = window.__pendingMap;
    console.log('[map-editor-bridge] pending map 已装·' + window.P.map.regions.length + ' 区');
    delete window.__pendingMap;
    return true;
  }
  return false;
};

// ============================================================
//  侧栏抽屉开关（点 rail → 滑出 overlay，× / Esc / [ ] 关闭）
// ============================================================
window.openSideDrawer = function(side, key){
  var id = (side === 'right' ? 'drawerRight' : 'drawerLeft');
  var el = document.getElementById(id);
  if (!el) return;
  el.classList.add('open');
  // 可选：依 key 滚到对应 panel（若存在该 data-key 元素）
  if (key){
    setTimeout(function(){
      try {
        var body = el.querySelector('.gs-drawer-body');
        var target = body && body.querySelector('[data-panel-key="'+key+'"]');
        if (target) target.scrollIntoView({behavior:'smooth', block:'start'});
      } catch(e){}
    }, 360);
  }
};
window.closeSideDrawer = function(side){
  var id = (side === 'right' ? 'drawerRight' : 'drawerLeft');
  var el = document.getElementById(id);
  if (el) el.classList.remove('open');
};
document.addEventListener('keydown', function(e){
  if (e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)) return;
  if (e.key === '[') { var l=document.getElementById('drawerLeft'); if(l){ l.classList.toggle('open'); e.preventDefault(); } }
  else if (e.key === ']') { var r=document.getElementById('drawerRight'); if(r){ r.classList.toggle('open'); e.preventDefault(); } }
  else if (e.key === 'Escape') { var l2=document.getElementById('drawerLeft'), r2=document.getElementById('drawerRight'); if(l2)l2.classList.remove('open'); if(r2)r2.classList.remove('open'); }
});
// 点击抽屉与 rail 之外的任意区域，自动关闭已打开的左右抽屉
document.addEventListener('mousedown', function(e){
  var l = document.getElementById('drawerLeft');
  var r = document.getElementById('drawerRight');
  var lOpen = l && l.classList.contains('open');
  var rOpen = r && r.classList.contains('open');
  if (!lOpen && !rOpen) return;
  var t = e.target;
  if (t && t.closest && (t.closest('.gs-drawer') || t.closest('.gs-rail-left') || t.closest('.gs-rail-right'))) return;
  if (lOpen) l.classList.remove('open');
  if (rOpen) r.classList.remove('open');
}, true);

